// Scratch repro for gh-1947 — mimics the CLI wiring: a background child
// spawn on a shared executor, completion delivered through
// TaskJobManager.completions, and the parent's reaction run executing
// schedule_message from the completion callback.
import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

final class _FakeFabric implements MessagingRepository {
  final sent = <AgentMessage>[];
  @override
  Future<void> send(AgentMessage message) async => sent.add(message);
  @override
  Future<void> register(String agentId,
      {String? sessionName, List<AgentCapability> capabilities = const []}) async {}
  @override
  Future<void> touch(String agentId, {bool busy = false}) async {}
  @override
  Future<List<AgentMessage>> peek(String agentId) async => const [];
  @override
  Future<List<AgentMessage>> drain(String agentId) async => const [];
  @override
  Future<List<MailboxEntry>> directory() async => const [];
}

AssistantMessage _assistant() => AssistantMessage(
    content: const [],
    api: 't',
    provider: 't',
    model: 'm',
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026));

AssistantMessageEventStream _textTurn(String text) {
  final empty = _assistant();
  final partial = AssistantMessage(
      content: [TextContent(text: text)],
      api: 't',
      provider: 't',
      model: 'm',
      usage: Usage.zero,
      stopReason: StopReason.stop,
      timestamp: DateTime.utc(2026));
  final s = AssistantMessageEventStream();
  s.push(StartEvent(partial: empty));
  s.push(TextStartEvent(contentIndex: 0, partial: empty));
  s.push(TextDeltaEvent(contentIndex: 0, delta: text, partial: partial));
  s.push(DoneEvent(reason: StopReason.stop, message: partial));
  s.end();
  return s;
}

Future<void> main() async {
  final fabric = _FakeFabric();
  final manager = SubagentManager(parentSessionId: 'sess', messaging: fabric)
    ..mailboxPrefix = 'sess';

  AgentTool? scheduleTool;
  final model = Model(
      id: 'm',
      api: 't',
      provider: 't',
      baseUrl: 'https://x',
      contextWindow: 100000,
      maxTokens: 4096);

  AssistantMessageEventStream streamFor(Model m, Context c,
      {CancelToken? cancelToken}) {
    final last = c.messages.last;
    final text = last is UserMessage ? last.content.toString() : '';
    if (text.contains('CHILD-TASK')) {
      return _textTurn('child done');
    }
    if (text.contains('REACTION')) {
      // The parent's reaction turn: call schedule_message with NO `to`.
      final call = ToolCall(id: 'c1', name: 'schedule_message',
          arguments: {'text': 'check on release', 'delay': '10m'});
      final partial = AssistantMessage(
          content: [call],
          api: 't',
          provider: 't',
          model: 'm',
          usage: Usage.zero,
          stopReason: StopReason.toolUse,
          timestamp: DateTime.utc(2026));
      final s = AssistantMessageEventStream();
      s.push(StartEvent(partial: _assistant()));
      s.push(ToolCallStartEvent(contentIndex: 0, partial: _assistant()));
      s.push(ToolCallEndEvent(contentIndex: 0, toolCall: call, partial: partial));
      s.push(DoneEvent(reason: StopReason.toolUse, message: partial));
      s.end();
      return s;
    }
    return _textTurn('done');
  }

  final executor = TaskExecutor(
    childTools: [
      AgentTool(
          name: 'read',
          description: 'read',
          tier: ApprovalTier.read,
          execute: (a, t, o) async => ToolExecutionResult.text('x')),
    ],
    streamFunction: streamFor,
    model: () => model,
    registry: TaskAgentRegistry(const []),
    semaphore: Semaphore(4),
    store: AgentOutputStore(),
    subagentManager: manager,
  );

  // Host wiring pattern for schedule_message (gh-970).
  scheduleTool = scheduleMessageTool(
    ScheduledMessageQueue(
      env: MemoryExecutionEnv(cwd: '/w'),
      repo: () => fabric,
      root: () => '/w/messages',
      selfMailbox: () => manager.mailboxOf('main'),
      ownerPrefix: () => 'sess',
    ),
    senderMailbox: () {
      final id = activeSubagentId();
      print('senderMailbox resolved: activeSubagentId()=$id');
      return id == null ? null : manager.mailboxOf(id);
    },
  );

  final jobManager = TaskJobManager();
  // completions listener registered in ROOT zone (the CLI REPL pattern).
  jobManager.completions.listen((job) {
    print('completion callback zone id: ${activeSubagentId()}');
    // The parent's reaction run starts here (root zone in the CLI).
    runReaction(job);
  });

  Future<TaskSingleResult> reactionDone = Future.value();

  void runReaction(TaskJob job) {
    // Reaction turn: a fresh Agent run for MAIN that calls schedule_message.
    final agent = Agent(
      model: model,
      streamFunction: streamFor,
      tools: [scheduleTool!],
    );
    agent.subscribe((event, _) {
      if (event is ToolResultEvent) {
        print('TOOL RESULT: ${event.result.text}');
      }
    });
    unawaited(agent.prompt('REACTION after ${job.id}').then((_) {
      print('reaction done, zone id: ${activeSubagentId()}');
    }));
  }

  // Background spawn pattern from _spawnBackground.
  final job = jobManager
      .register(id: 'pending', index: 0, agent: 'task', task: 't');
  unawaited(
    executor
        .runSpawn(
          item: const TaskItem(name: 'qjs_race', task: 'CHILD-TASK'),
          index: 0,
          context: 'ctx',
          preallocatedId: 'qjs_race',
        )
        .then((result) {
          print('_finish zone id: ${activeSubagentId()}');
          jobManager._finishPublic(job, result);
        }),
  );
  await Future<void>.delayed(const Duration(seconds: 2));
}

