// Scratch repro gh-1947 case (c): parent BUSY in a soft-yield tool phase;
// child completes mid-phase; completion listener steers the parent; the
// steering is delivered at the phase boundary and the NEXT tool call is
// schedule_message. Print the zone identity + the record's `to`.
import 'dart:async';
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

final class _FakeFabric implements MessagingRepository {
  final sent = <AgentMessage>[];
  @override
  Future<void> send(AgentMessage message) async => sent.add(message);
  @override
  Future<void> register(
    String agentId, {
    String? sessionName,
    List<AgentCapability> capabilities = const [],
  }) async {}
  @override
  Future<void> touch(String agentId, {bool busy = false}) async {}
  @override
  Future<List<AgentMessage>> peek(String agentId) async => const [];
  @override
  Future<List<AgentMessage>> drain(String agentId) async => const [];
  @override
  Future<List<MailboxEntry>> directory() async => const [];
}

AssistantMessage _assistant({
  List<ContentBlock> content = const [],
  StopReason stopReason = StopReason.stop,
}) => AssistantMessage(
  content: content,
  api: 't',
  provider: 't',
  model: 'm',
  usage: Usage.zero,
  stopReason: stopReason,
  timestamp: DateTime.utc(2026),
);

AssistantMessageEventStream _turn(List<AssistantMessageEvent> events) {
  final s = AssistantMessageEventStream();
  for (final e in events) {
    s.push(e);
  }
  s.end();
  return s;
}

List<AssistantMessageEvent> _textTurn(String text) {
  final empty = _assistant();
  final partial = _assistant(content: [TextContent(text: text)]);
  return [
    StartEvent(partial: empty),
    TextStartEvent(contentIndex: 0, partial: empty),
    TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
    DoneEvent(reason: StopReason.stop, message: partial),
  ];
}

List<AssistantMessageEvent> _toolTurn(List<ToolCall> calls) {
  final empty = _assistant();
  final partial = _assistant(
    content: calls,
    stopReason: StopReason.toolUse,
  );
  final events = <AssistantMessageEvent>[StartEvent(partial: empty)];
  for (var i = 0; i < calls.length; i++) {
    events
      ..add(ToolCallStartEvent(contentIndex: i, partial: empty))
      ..add(ToolCallEndEvent(contentIndex: i, toolCall: calls[i], partial: partial));
  }
  events.add(DoneEvent(reason: StopReason.toolUse, message: partial));
  return events;
}

Future<void> main() async {
  final fabric = _FakeFabric();
  final manager = SubagentManager(parentSessionId: 'sess', messaging: fabric)
    ..mailboxPrefix = 'sess';
  final model = Model(
    id: 'm',
    api: 't',
    provider: 't',
    baseUrl: 'https://x',
    contextWindow: 100000,
    maxTokens: 4096,
  );

  var scheduleCalls = 0;
  final records = <Map<String, dynamic>>[];
  final scheduleTool = scheduleMessageTool(
    ScheduledMessageQueue(
      env: MemoryExecutionEnv(cwd: '/w'),
      repo: () => fabric,
      root: () => '/w/messages',
      selfMailbox: () => manager.mailboxOf('main'),
      ownerPrefix: () => 'sess',
    ),
    senderMailbox: () {
      final id = activeSubagentId();
      print('  [senderMailbox] activeSubagentId()=$id');
      return id == null ? null : manager.mailboxOf(id);
    },
  );

  // A yield-aware gated tool: holds until released or soft-yielded.
  final gate = Completer<void>();
  final gateTool = AgentTool(
    name: 'gated_work',
    description: 'long work',
    tier: ApprovalTier.read,
    execute: (args, cancelToken, onUpdate) async {
      final yieldToken = currentYieldToken();
      print('  [gated_work] started, yield token: ${yieldToken != null}');
      try {
        await Future.any([
          gate.future,
          if (yieldToken != null)
            yieldToken.onCancel.then(
              (_) => throw CancelledException(yieldToken.cancelReason),
            ),
        ]);
      } on CancelledException {
        print('  [gated_work] soft-yielded early');
        return ToolExecutionResult.text('yielded; work continues');
      }
      return ToolExecutionResult.text('work done');
    },
  );

  AssistantMessageEventStream streamFor(Model m, Context c,
      {CancelToken? cancelToken}) {
    final last = c.messages.last;
    final text = last is UserMessage ? last.content.toString() : '';
    if (text.contains('CHILD-TASK')) {
      return _turn(_textTurn('child done'));
    }
    if (text.contains('SPAWN')) {
      return _turn(_toolTurn([
        ToolCall(
          id: 'c-task',
          name: 'task',
          arguments: {
            'context': 'ctx',
            'tasks': [
              {'name': 'qjs_race', 'task': 'CHILD-TASK'},
            ],
            'background': true,
          },
        ),
        ToolCall(id: 'c-gate', name: 'gated_work', arguments: {}),
      ]));
    }
    if (text.contains('REACTION')) {
      scheduleCalls++;
      return _turn(_toolTurn([
        ToolCall(id: 'c-sched', name: 'schedule_message', arguments: {
          'text': 'check on release',
          'delay': '10m',
        }),
      ]));
    }
    if (text.contains('WRAP')) {
      return _turn(_textTurn('all done'));
    }
    return _turn(_textTurn('done'));
  }

  final taskConfig = TaskToolConfig(
    childTools: [scheduleTool],
    streamFunction: () => streamFor,
    model: () => model,
    subagentManager: manager,
    defaultBackground: true,
  );
  final taskT = taskTool(config: taskConfig);

  final jobManager = taskConfig.jobManager;
  final reacted = Completer<void>();
  jobManager.completions.listen((job) {
    print('completion: zone id=${activeSubagentId()}');
    // Busy mid-phase in the real CLI → steer; the boundary delivers it.
    mainAgent.steer(
      UserMessage.text('REACTION: schedule the follow-up now'),
    );
    // Then let the run end afterwards.
    Timer(const Duration(milliseconds: 50), () {
      mainAgent.followUp(UserMessage.text('WRAP up'));
    });
  });

  final mainAgent = Agent(
    model: model,
    streamFunction: streamFor,
    toolExecutor: ToolRegistry([taskT, scheduleTool, gateTool]).executor,
    tools: [taskT, scheduleTool, gateTool],
  );
  mainAgent.subscribe((event, _) {
    if (event is MessageEndEvent && event.message is ToolResultMessage) {
      final m = event.message as ToolResultMessage;
      print('  [tool result] ${m.content.map((c) => c is TextContent ? c.text : c.toString()).join()}');
    }
    if (event is AgentEndEvent) {
      print('agent end');
      if (!reacted.isCompleted) reacted.complete();
    }
  });
  await mainAgent
      .prompt('SPAWN a child and hold the gate')
      .timeout(const Duration(seconds: 15), onTimeout: () => []);
  // Let the completion + steering play out.
  await Future<void>.delayed(const Duration(milliseconds: 300));
  gate.complete(); // release the gate in case the yield did not fire
  await Future<void>.delayed(const Duration(milliseconds: 800));
  for (final r in records) {
    print('record: to=${r['to']} from=${r['from']}');
  }
  print('done');
  exit(0);
}

