/// `schedule_message` — send a delayed note to an agent mailbox (self by
/// default), so an agent can schedule its own follow-up task. Backed by
/// [ScheduledMessageQueue]; pending records persist across restarts.
library;

import '../agent/agent_loop.dart';
import '../agent/agent_tool.dart';
import '../approval/approval.dart';
import 'scheduled_messages.dart';

/// Parses `90s` / `25m` / `2h` / `1d` (and combinations like `1h30m`).
Duration? parseDelay(String spec) {
  final re = RegExp(r'^(\d+(?:\.\d+)?)(ms|s|m|h|d)');
  var total = Duration.zero;
  var rest = spec.trim();
  while (rest.isNotEmpty) {
    final m = re.firstMatch(rest);
    if (m == null) return null;
    final value = double.parse(m.group(1)!);
    total += switch (m.group(2)!) {
      // All in milliseconds so fractional units work ('0.5m' = 30 s) and
      // 'ms' is not accidentally a thousand-fold (bug: 90ms = 90 seconds).
      'ms' => Duration(milliseconds: value.round()),
      's' => Duration(milliseconds: (value * 1000).round()),
      'm' => Duration(milliseconds: (value * 60000).round()),
      'h' => Duration(milliseconds: (value * 3600000).round()),
      _ => Duration(milliseconds: (value * 86400000).round()),
    };
    rest = rest.substring(m.end);
  }
  return total == Duration.zero ? null : total;
}

AgentTool scheduleMessageTool(
  ScheduledMessageQueue queue, {

  /// The calling agent's own mailbox when it is NOT the host's main agent
  /// (gh-970): a subagent scheduling a self-reminder must default to its
  /// OWN mailbox — the queue's `selfMailbox` always resolves the host's
  /// main mailbox, which silently redirected every subagent reminder into
  /// main's inbox. Resolved per call; null (the main agent) keeps the
  /// legacy defaulting. Hosts wire it to the subagent scope, e.g.
  /// `() => activeSubagentId() == null ? null : manager.mailboxOf(...)`.
  String? Function()? senderMailbox,
}) {
  return AgentTool(
    name: 'schedule_message',
    description:
        'Send a delayed message to an agent mailbox (your own by default) '
        '— schedule a follow-up task to check on something later. The '
        'message wakes the recipient when it fires; it survives restarts.',
    parameters: {
      'type': 'object',
      'properties': {
        'text': {
          'type': 'string',
          'description': 'The message to deliver when the timer fires.',
        },
        'delay': {
          'type': 'string',
          'description':
              'How long to wait: 90s / 25m / 2h / 1d (combinable, e.g. '
              '1h30m).',
        },
        'to': {
          'type': 'string',
          'description': 'Recipient mailbox id; defaults to your own mailbox.',
        },
      },
      'required': ['text', 'delay'],
    },
    tier: ApprovalTier.write,
    execute: (args, cancelToken, onUpdate) async {
      final text = args['text'] as String? ?? '';
      final delay = parseDelay(args['delay'] as String? ?? '');
      if (text.trim().isEmpty) {
        return ToolExecutionResult.text('error: text is required');
      }
      if (delay == null) {
        return ToolExecutionResult.text(
          'error: delay must look like 90s / 25m / 2h / 1d',
        );
      }
      final sender = senderMailbox?.call();
      final id = await queue.schedule(
        text: text.trim(),
        delay: delay,
        to: (args['to'] as String?) ?? sender,
        from: sender,
      );
      final due = DateTime.now().add(delay).toIso8601String();
      // CROSS-TOOL CONTRACT: the obligations ledger's pending-wait arming
      // (AgentCliPersist.recordPendingWait) parses the scheduled id out
      // of this line's `scheduled <id> for ` prefix — keep it stable or
      // update both sides together (pinned by
      // test/cli/agent_cli_persist_pending_wait_test.dart).
      return ToolExecutionResult.text(
        'scheduled $id for $due — it will arrive as [scheduled] mail'
        '${sender == null ? '' : ' in $sender'}',
      );
    },
  );
}

/// Zone-scoped identity of the subagent whose run encloses the caller.
///
/// The executor's in-flight id STACK cannot attribute tool calls under
/// concurrency: several background children run on ONE executor, so the
/// stack's head is "the child that started last", not "the child executing
/// this tool call" — gh-970's swapped sender envelopes. Each child run
/// therefore publishes its id in a zone value (the same mechanism as the
/// soft-yield token, `cancel_token.dart`) and identity consumers read it at
/// call time: the child-only `reply`/`agent_message` tools resolve the
/// calling child through the executor, and shared tools with self-mailbox
/// semantics (`schedule_message`) resolve the caller's mailbox through the
/// host wiring.
library;

import 'dart:async';

/// Zone key under which a child runner publishes the running child's id.
const Symbol subagentIdZoneKey = #fahSubagentId;

/// The id of the subagent whose run encloses the caller, or null when the
/// caller is not inside a child run (the main agent, host code).
String? activeSubagentId() => Zone.current[subagentIdZoneKey] as String?;

/// Runs [body] with [id] published as the enclosing subagent identity.
/// Nested scopes shadow outer ones; the value is visible to every callback
/// executed within [body]'s async chain (tool executions included).
R runWithSubagentScope<R>(String id, R Function() body) =>
    runZoned(body, zoneValues: {subagentIdZoneKey: id});

