@TestOn('vm')
library;

/// gh-1947 — `schedule_message` recipient resolution on the MAIN agent:
///
/// - The default recipient ("your own mailbox") must be the caller's own
///   mailbox — for the orchestrator that is `<sessionId>/main`, NEVER a
///   task-spawned child's mailbox, no matter what subagent activity
///   (background spawn, delivered task-result, wake sweep) surrounds the
///   call.
/// - An explicit `to:` must be honored verbatim, and the tool response
///   must name the recipient the record actually carries.
///
/// Driven through the REAL AgentCli (the same wiring the REPL boots:
/// `scheduleSenderMailbox: _childSenderMailbox` over the zone scope).

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

String messageText(Object message) {
  final content = switch (message) {
    UserMessage() => message.content,
    AssistantMessage() => message.content,
    ToolResultMessage() => message.content,
    AgentMessage() => message.text,
    _ => '',
  };
  return content is String
      ? content
      : content is List<ContentBlock>
      ? [
          for (final block in content)
            if (block is TextContent) block.text,
        ].join('\n')
      : '';
}

/// Routes every model call by the last user message:
/// - child runs (the child task marker) answer and finish;
/// - the reaction run after a delivered task-result replays the
///   schedule turn produced by [reactionTurns];
/// - everything else replays [leadTurns] then a plain text answer.
class _Router {
  _Router({
    required this.childTask,
    required List<List<AssistantMessageEvent>> leadTurns,
    this.reactionTurns,
  }) : _leadTurns = List.of(leadTurns);

  final String childTask;
  final List<List<AssistantMessageEvent>> _leadTurns;
  final List<List<AssistantMessageEvent>>? reactionTurns;
  final contexts = <Context>[];

  bool _childSpawned = false;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final text = context.messages.reversed
        .map(messageText)
        .firstWhere((t) => t.isNotEmpty, orElse: () => '');
    final stream = AssistantMessageEventStream();
    final turn = _route(text);
    for (final event in turn) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }

  List<AssistantMessageEvent> _route(String text) {
    if (text.contains(childTask)) {
      return textTurn('child work finished');
    }
    if (text.contains('<task-result')) {
      _childSpawned = true;
      final turns = reactionTurns;
      if (turns != null && turns.isNotEmpty) {
        return turns.removeAt(0);
      }
    }
    if (_leadTurns.isNotEmpty) {
      return _leadTurns.removeAt(0);
    }
    return textTurn('done');
  }
}

void main() {
  late FakeCliIO io;

  setUp(() => io = FakeCliIO());
  tearDown(() => io.close());

  Future<(AgentCli, Future<void>)> bootedCli(StreamFunction stream) async {
    final cli = AgentCli(
      config: AgentCliConfig(
        model: testModel,
        apiKey: 'test-key',
        env: MemoryExecutionEnv(cwd: '/work', shell: const UnavailableShell()),
        sessionRoot: '/sessions',
        approvalMode: ApprovalMode.yolo,
      ),
      io: io,
      streamFunction: stream,
    );
    final run = cli.run();
    io.sendLine('/help');
    await waitForIt(
      () => io.out.toString().contains('/tasks'),
      reason: 'REPL is up',
    );
    return (cli, run);
  }

  /// Waits until a scheduled record file exists and parses it.
  Future<Map<String, dynamic>> scheduledRecord(
    MemoryExecutionEnv env,
    String id,
  ) async {
    final dir = '/sessions/${encodeSessionCwd('/work')}/messages/_scheduled';
    for (var i = 0; i < 400; i++) {
      final text = (await env.readTextFile('$dir/$id.json')).valueOrNull;
      if (text != null) {
        final decoded = jsonDecode(text);
        if (decoded is Map<String, dynamic>) return decoded;
      }
      await Future<void>.delayed(const Duration(milliseconds: 25));
    }
    fail('scheduled record $id never appeared');
  }

  test(
    'gh-1947 AC1: a main-agent schedule after a delivered task-result '
    'defaults to MAIN, not the child',
    timeout: const Timeout(Duration(seconds: 180)),
    () async {
      const childTask = 'child-task: qjs_race race run';
      final router = _Router(
        childTask: childTask,
        leadTurns: [
          toolTurn([
            ToolCall(
              id: 't1',
              name: 'task',
              arguments: const {
                'context': 'ctx',
                'background': true,
                'tasks': [
                  {'name': 'qjs_race', 'agent': 'task', 'task': childTask},
                ],
              },
            ),
          ]),
          textTurn('spawned qjs_race in the background'),
        ],
        // The reaction run after `<task-result`: schedule with the
        // DEFAULT recipient (no `to`).
        reactionTurns: [
          toolTurn([
            ToolCall(
              id: 't2',
              name: 'schedule_message',
              arguments: const {'text': 'check the release', 'delay': '10m'},
            ),
          ]),
          textTurn('scheduled the follow-up'),
        ],
      );
      final (cli, run) = await bootedCli(router.call);

      io.sendLine('spawn qjs_race');
      await waitForIt(
        () => cli.taskConfig.jobManager.job('qjs_race') != null,
        reason: 'the background child registers',
      );
      // The child finishes; the completion notice re-enters as a fresh
      // run (idle wake), whose scripted reaction schedules the timer.
      await waitForIt(
        () => io.out.toString().contains('scheduled '),
        reason: 'the reaction run executed schedule_message',
      );
      final out = io.out.toString();
      final match = RegExp(r'scheduled (\S+) for ').firstMatch(out);
      expect(match, isNotNull, reason: 'the tool reported a schedule id');
      final id = match!.group(1)!;

      final env = cli.config.env as MemoryExecutionEnv;
      final record = await scheduledRecord(env, id);
      final to = record['to'] as String;
      expect(
        to.endsWith('/main'),
        isTrue,
        reason:
            'gh-1947: the default recipient must be the caller’s own '
            'mailbox (<session>/main) — got $to',
      );
      expect(
        to.endsWith('/qjs_race'),
        isFalse,
        reason: 'the timer must not land in the child mailbox',
      );
      // The response line names the mailbox the record actually carries.
      expect(out.contains('in $to'), isTrue);
      io.sendLine('/exit');
      await run;
    },
  );

  test(
    'gh-1947 AC2: an explicit to: is honored verbatim and the response '
    'names the recorded recipient',
    timeout: const Timeout(Duration(seconds: 180)),
    () async {
      const childTask = 'child-task: qjs_race race run';
      final router = _Router(
        childTask: childTask,
        leadTurns: [
          toolTurn([
            ToolCall(
              id: 't1',
              name: 'task',
              arguments: const {
                'context': 'ctx',
                'background': true,
                'tasks': [
                  {'name': 'qjs_race', 'agent': 'task', 'task': childTask},
                ],
              },
            ),
          ]),
          textTurn('spawned qjs_race in the background'),
        ],
        reactionTurns: [
          toolTurn([
            ToolCall(
              id: 't2',
              name: 'schedule_message',
              arguments: const {
                'text': 'check the release',
                'delay': '10m',
                'to': 'explicit-session/main',
              },
            ),
          ]),
          textTurn('scheduled the follow-up'),
        ],
      );
      final (cli, run) = await bootedCli(router.call);

      io.sendLine('spawn qjs_race');
      await waitForIt(
        () => io.out.toString().contains('scheduled '),
        reason: 'the reaction run executed schedule_message',
      );
      final out = io.out.toString();
      final match = RegExp(r'scheduled (\S+) for ').firstMatch(out);
      expect(match, isNotNull);
      final id = match!.group(1)!;

      final env = cli.config.env as MemoryExecutionEnv;
      final record = await scheduledRecord(env, id);
      expect(record['to'], 'explicit-session/main');
      // The response must name the RECORDED recipient — never the zone
      // participant (the gh-1947 reporting bug printed the sender).
      expect(out.contains('in explicit-session/main'), isTrue);
      io.sendLine('/exit');
      await run;
    },
  );
}

